async (page) => {
  const { execSync } = require('child_process');

  try {
    // Get process information with memory usage
    // Using ps command to get PID, process name, and memory usage
    const output = execSync('ps aux --sort=-%mem | head -20', { encoding: 'utf-8' });
    return output;
  } catch (error) {
    return `Error: ${error.message}`;
  }
}
